  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 Earth's Oceans$j$, $j${"readings": [{"title": "Psalm 107 (King James Version)", "url": "/portal/bible/Psalms/107"}], "body": "Oceans cover most of our planet. Psalm 107:23 and 24 say, They that go down to the sea in ships, that do business in great waters; these see the works of the LORD, and his wonders in the deep. Genesis 1:10 says that God called the gathering together of the waters Seas. Ecclesiastes 1:7 adds, All the rivers run into the sea; yet the sea is not full.\n\nOceans cover about 71 percent of Earth's surface and hold about 97 percent of Earth's water. There are five named oceans: Pacific, Atlantic, Indian, Southern and Arctic, and the Pacific is the largest. The average salinity, the amount of dissolved salt, is about 35 parts per thousand, or 3.5 percent, and the main salt is sodium chloride. Salinity is higher where evaporation is strong and lower where rivers and rain add fresh water. Ocean temperature varies with depth. Warm water sits in a sunlit surface layer, a layer of rapid change called the thermocline lies below it, and the deep ocean is cold and dark.\n\nOcean water is always moving. Surface currents are driven by wind and bent by the Coriolis effect, forming large circular patterns called gyres. The Gulf Stream is a warm, fast current that begins in the Gulf of Mexico, flows through the Florida Straits just off the coast of Pompano Beach, and then crosses the North Atlantic. It keeps western Europe milder than other places at the same latitude. Deep currents are driven by differences in density. Cold, salty water is dense and sinks near the poles, and this slow global circulation moves heat around the planet over hundreds of years.\n\nWaves are caused mostly by wind. A wave has a crest, a trough and a wavelength, and the wave carries energy, not water, across the ocean. Tsunamis are caused by sudden movement of the seafloor, not by wind. Tides come from the pull of the Moon and Sun, as you learned in Unit 1. Rip currents are narrow channels of water flowing away from shore. If you are caught in one, do not fight it. Swim parallel to the shore until you are out of the current, then swim back in.\n\nThe ocean is full of life. Florida has the only living coral barrier reef in the continental United States, the Florida Reef Tract, which runs from near Miami and Broward County to the Dry Tortugas. Reefs shelter fish, protect the coast and support fishing and tourism. Corals are sensitive to warm water, pollution and damage from boats and divers.\n\nYour task: (1) Give facts about the oceans' size and salinity. (2) Explain how surface currents and deep currents differ. (3) Describe what to do in a rip current.\n\nFlorida standards: SC.912.E.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.7", "script": "Welcome back. Listen, Psalm 107:23 and 24 say, They that go down to the sea in ships, that do business in great waters; these see the works of the LORD, and his wonders in the deep.\n\nNow watch this. Oceans cover about 71 percent of Earth and hold about 97 percent of its water. The average salinity is about 35 parts per thousand. The surface is warm and sunlit. Below it is the thermocline, and the deep ocean is cold and dark.\n\nSurface currents are pushed by wind and bent by the Coriolis effect into gyres. The Gulf Stream starts in the Gulf of Mexico, flows through the Florida Straits just off Pompano Beach and crosses the Atlantic, keeping western Europe mild. Deep currents are driven by density. Cold, salty water sinks near the poles.\n\nWaves are mostly caused by wind and carry energy, not water. Tsunamis come from sudden movement of the seafloor. If you are caught in a rip current, do not fight it. Swim parallel to shore, then swim back in.\n\nFlorida has the only living coral barrier reef in the continental United States. Reefs shelter fish and protect the coast, and they are sensitive to heat and pollution.\n\nYour task is to give ocean facts, compare currents and explain what to do in a rip current. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 Earth's Oceans$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 Climate and Climate Change$j$, $j${"readings": [{"title": "Genesis 8 (King James Version)", "url": "/portal/bible/Genesis/8"}], "body": "Weather is the condition of the atmosphere at a place and time. Climate is the average weather of a region over a long time, usually 30 years or more. Genesis 8:22 says, While the earth remaineth, seedtime and harvest, and cold and heat, and summer and winter, and day and night shall not cease. God built regular patterns into the earth.\n\nSeveral factors shape a region's climate. Latitude is the most important, because sunlight is most direct near the equator. Elevation matters, because air cools with height. Nearness to a large body of water makes temperatures milder, and ocean currents move heat, as the Gulf Stream does. Mountains block moisture and make dry rain shadows on their far sides. Scientists group climates into tropical, dry, temperate, continental and polar zones. Most of Florida has a humid subtropical climate, and the far south of the state is tropical, with a hot, wet summer and a mild, drier winter.\n\nEarth's climate has changed many times. Ice ages came and went. Natural causes include changes in Earth's orbit and tilt, changes in the Sun's output, volcanic eruptions and shifts in ocean currents. Scientists learn about past climates from ice cores, tree rings and ocean sediments.\n\nToday most climate scientists report that Earth is warming. Measurements show that the global average temperature has risen roughly 1.1 to 1.3 degrees Celsius since the late 1800s, sea level has risen about eight inches since 1880, and glaciers and Arctic sea ice have shrunk. The amount of carbon dioxide in the air has risen from about 280 parts per million before the Industrial Revolution to more than 420 parts per million today, as shown by air samples since 1958 and by ice cores. Carbon dioxide and methane trap heat, and burning coal, oil and natural gas adds carbon dioxide. Major scientific organizations conclude that human activity is the main cause of the warming seen since the middle of the twentieth century. Scientists are still working to improve predictions of how much warming will come and how it will affect each region.\n\nWhat to do about climate change is a question of economics, energy, fairness and values, and thoughtful people, including Christians, disagree about the best responses. Believers can agree on facts that are well measured, on honest and humble debate, on helping those hurt by disasters, and on caring for the earth. Florida's low coast is especially exposed to higher seas and stronger flooding, so planning and preparation matter here.\n\nYour task: (1) Tell the difference between weather and climate. (2) Name four factors that affect climate. (3) Describe three pieces of evidence that Earth's climate is warming.\n\nFlorida standards: SC.912.E.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.7", "script": "Welcome back. Listen, Genesis 8:22 says, While the earth remaineth, seedtime and harvest, and cold and heat, and summer and winter, and day and night shall not cease. God built regular patterns into the earth.\n\nNow watch this. Weather is the condition of the air at a place and time. Climate is the average weather over 30 years or more. Latitude, elevation, nearness to water, ocean currents and mountains all shape climate. Most of Florida is humid subtropical, and the far south is tropical.\n\nClimate has changed before. Ice ages came and went, because of orbit and tilt changes, the Sun's output, volcanoes and ocean currents. Scientists read ice cores, tree rings and ocean sediments.\n\nLook at today. Measurements show the average global temperature is up roughly 1.1 to 1.3 degrees Celsius since the late 1800s. Sea level is up about eight inches since 1880. Carbon dioxide has risen from about 280 parts per million to more than 420. Major scientific organizations conclude that human activity is the main cause of recent warming. Scientists are still improving predictions.\n\nWhat to do about it is a question of economics, energy and values, and thoughtful Christians disagree. We can agree on measured facts, humble debate, helping those hurt by disasters and caring for the earth.\n\nYour task is to tell weather from climate, name climate factors and describe evidence of warming. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 Climate and Climate Change$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 Water Resources and Human Impact$j$, $j${"readings": [{"title": "John 4 (King James Version)", "url": "/portal/bible/John/4"}], "body": "Water is one of the most precious gifts God has given. John 4:14 records the words of Jesus, but whosoever drinketh of the water that I shall give him shall never thirst; but the water that I shall give him shall be in him a well of water springing up into everlasting life. Isaiah 55:1 says, Ho, every one that thirsteth, come ye to the waters. Fresh water is a daily need, and it is also a picture of grace.\n\nAbout 97 percent of Earth's water is salt water. Of the 3 percent that is fresh, most is frozen in glaciers and ice sheets or lies deep underground, so less than 1 percent of Earth's water is easy to reach in rivers, lakes and shallow groundwater. A watershed is all of the land that drains into a river, lake or bay. What happens anywhere in a watershed can affect the water downstream.\n\nFlorida is rich in water. Rain, springs, lakes, rivers and aquifers supply the state, and the Everglades is a wide, shallow river of grass that slowly moves water south from Lake Okeechobee to Florida Bay. Marjory Stoneman Douglas described it as the River of Grass in her 1947 book. In the 1900s canals and levees drained much of the Everglades to build farms and cities. This changed the flow of water and harmed wildlife. The Comprehensive Everglades Restoration Plan, approved in 2000, aims to restore more natural flow while still protecting people from floods. In southeast Florida, drinking water comes from the Biscayne aquifer, and rising seas and heavy pumping can push salt water into it.\n\nHuman activity can pollute water. Point source pollution comes from one place, such as a pipe. Nonpoint source pollution comes from many places, such as fertilizer, oil and animal waste washed off lawns, farms and streets by rain. Extra nutrients can feed algae blooms that use up oxygen and harm fish. Red tide, a bloom of a tiny organism called Karenia brevis, happens naturally in the Gulf of Mexico but can be worsened by nutrients, and it can kill sea life and irritate breathing.\n\nDrinking water is treated in several steps, including screening out large debris, adding chemicals that make particles clump, letting them settle, filtering the water and disinfecting it. We can conserve water by fixing leaks, watering lawns only when needed and at the right hours, taking shorter showers, using native plants and never dumping chemicals down storm drains.\n\nYour task: (1) Explain why so little of Earth's water is usable. (2) Describe how the Everglades has been changed and why restoration matters. (3) List four ways to protect water.\n\nFlorida standards: SC.912.E.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.7", "script": "Welcome back. Listen, John 4:14 records the words of Jesus, but whosoever drinketh of the water that I shall give him shall never thirst. Fresh water is a daily need, and it is a picture of grace.\n\nNow watch this. About 97 percent of Earth's water is salt water. Of the 3 percent that is fresh, most is frozen or deep underground, so less than 1 percent is easy to reach. A watershed is all the land that drains into a river, lake or bay. What happens upstream affects everything downstream.\n\nLook at Florida. The Everglades is a shallow river of grass that moves water slowly south from Lake Okeechobee. In the 1900s canals drained much of it, which changed the flow and harmed wildlife. The restoration plan approved in 2000 aims to restore natural flow while protecting people from floods. In Broward County our drinking water comes from the Biscayne aquifer, and heavy pumping and rising seas can push in salt water.\n\nPollution from one pipe is point source. Pollution washed off lawns, farms and streets is nonpoint source. Extra nutrients can feed algae blooms. Red tide is natural but can be worsened by nutrients.\n\nWe can fix leaks, water only when needed, use native plants and never dump chemicals down storm drains.\n\nYour task is to explain why little water is usable, describe the Everglades and list ways to protect water. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 Water Resources and Human Impact$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Earth's Resources, Stewardship and Careers$j$, $j${"readings": [{"title": "Psalm 24 (King James Version)", "url": "/portal/bible/Psalms/24"}, {"title": "Genesis 2 (King James Version)", "url": "/portal/bible/Genesis/2"}], "body": "The earth and its riches are the Lord's gift to us and to those who come after us. Psalm 24:1 says, The earth is the LORD's, and the fulness thereof; the world, and they that dwell therein. Genesis 1:28 gives mankind dominion, and Genesis 2:15 shows what dominion means: the LORD God took the man, and put him into the garden of Eden to dress it and to keep it. Dominion is faithful care, not careless taking.\n\nNatural resources are materials from the earth that people use. Renewable resources, such as sunlight, wind, water, trees and fish, can be replaced naturally if used wisely. Nonrenewable resources, such as coal, oil, natural gas and minerals, form so slowly that they cannot be replaced in a human lifetime. Using renewable resources faster than they can recover, as in overfishing or cutting forests faster than they regrow, turns them into scarce resources.\n\nMining supplies metals, stone, sand and fuels, but it can scar the land, create waste and pollute water. Responsible companies plan mines, protect streams and reclaim the land afterward. Cities and farms cover land that once was wild, and good land use planning leaves room for farms, homes, businesses and natural areas. Wetlands protect coasts from flooding, clean water and shelter wildlife.\n\nWaste is a growing challenge. Landfills hold what we throw away, and plastic can last for hundreds of years. The wise rule is reduce, reuse, recycle. Reduce what you buy, reuse what you can, and recycle paper, metal, glass and many plastics. Composting turns food scraps and yard waste into rich soil. Energy conservation also saves money and cuts pollution.\n\nEarth science offers many careers. Geologists study rocks and look for water, minerals and energy. Meteorologists forecast weather and warn of hurricanes. Oceanographers study the sea. Hydrologists manage water. Astronomers explore space. Environmental scientists and engineers clean and protect land, air and water. Emergency managers prepare communities for storms and floods. Surveyors, park rangers, teachers and farmers also use earth science. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men. Every one of these jobs can be a calling.\n\nYour task: (1) Tell the difference between renewable and nonrenewable resources. (2) Explain reduce, reuse and recycle. (3) Describe one earth science career and how it can serve people.\n\nFlorida standards: SC.912.E.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.7", "script": "Welcome back. Listen, Psalm 24:1 says, The earth is the LORD's, and the fulness thereof; the world, and they that dwell therein. Genesis 2:15 shows what dominion means: the LORD God put the man into the garden to dress it and to keep it. Dominion is faithful care, not careless taking.\n\nNow watch this. Renewable resources, like sunlight, wind, water, trees and fish, can be replaced if used wisely. Nonrenewable resources, like coal, oil, natural gas and minerals, form too slowly to replace in a human lifetime. Overfishing or cutting forests faster than they regrow turns a renewable resource into a scarce one.\n\nMining can scar land and pollute water. Responsible companies protect streams and reclaim the land afterward. Wetlands protect coasts, clean water and shelter wildlife.\n\nFor waste, remember reduce, reuse, recycle. Composting turns scraps into rich soil. Saving energy saves money and cuts pollution.\n\nEarth science careers include geologist, meteorologist, oceanographer, hydrologist, astronomer, environmental engineer and emergency manager. Colossians 3:23 says, whatsoever ye do, do it heartily, as to the Lord. Every one of these jobs can be a calling.\n\nYour task is to compare resources, explain reduce, reuse and recycle and describe a career. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Earth's Resources, Stewardship and Careers$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Oceans, Climate, Water and Stewardship$j$, $j${"prompt": "Write a report of at least 250 words on oceans, climate, water and stewardship. Use complete sentences, show every calculation and label each part. Psalm 24:1 says, The earth is the LORD's, and the fulness thereof; the world, and they that dwell therein.\n\nPart 1: Give the percent of Earth covered by oceans, the average salinity, and the difference between surface and deep currents. Describe the Gulf Stream and its path past Florida.\nPart 2: Tell the difference between weather and climate, name four factors that affect climate, and name the climate type of most of Florida.\nPart 3: Describe three pieces of evidence that Earth has warmed, explain the role of greenhouse gases, and explain why thoughtful people, including Christians, may disagree on the best responses while still agreeing on caring for the earth.\nPart 4: Explain why less than 1 percent of Earth's water is easy to reach. Describe the Everglades, the Biscayne aquifer and one threat to each. Give four ways households can protect and conserve water.\nPart 5: Compare renewable and nonrenewable resources with two examples each. Explain reduce, reuse and recycle, and describe one earth science career and how Genesis 2:15 and Colossians 3:23 apply to it.", "rubric": "100 points. Part 1: 20 points. Part 2: 15 points. Part 3: 25 points. Part 4: 20 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Oceans, Climate, Water and Stewardship$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: Keepers of the Garden$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a place of natural beauty near you, such as a beach, a park, a canal or the Everglades, and why it matters, (2) explains in your own words one way people affect water, land, air or climate, (3) explains what it means for believers to dress and keep the earth, and gives one practical action your family or church could take, and (4) connects your answer to Psalm 24:1, Genesis 2:15 or John 4:14. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can you use what you learned in earth and space science to serve others and honor God? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: Keepers of the Garden$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: Earth's Oceans$j$, $j${"questions": [{"q": "Oceans cover about what fraction of Earth's surface?", "options": ["30 percent", "50 percent", "90 percent", "71 percent"]}, {"q": "The Gulf Stream is a:", "options": ["Deep cold current", "Tsunami", "Warm surface current that flows past Florida", "Type of tide"]}, {"q": "Deep ocean currents are driven mainly by differences in:", "options": ["Waves", "Wind speed", "Moon phases", "Density"]}, {"q": "If you are caught in a rip current, you should:", "options": ["Dive to the bottom", "Swim straight against it", "Panic", "Swim parallel to the shore"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Earth's Oceans$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,3,3}'::int[], array[$j$Oceans cover most of the planet.$j$,$j$It flows through the Florida Straits and across the Atlantic.$j$,$j$Cold, salty water is dense and sinks.$j$,$j$Rip currents are narrow and you can swim out of them sideways.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Earth's Oceans$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: Climate and Climate Change$j$, $j${"questions": [{"q": "Climate is best described as the:", "options": ["Temperature at noon", "Weather today", "Average weather of a region over many years", "Weather this week"]}, {"q": "Which factor has the greatest effect on a region's climate?", "options": ["The number of cities", "The color of the soil", "Latitude", "The name of the country"]}, {"q": "Carbon dioxide and methane affect climate because they:", "options": ["Make the Sun brighter", "Trap heat in the atmosphere", "Cool the oceans", "Cause earthquakes"]}, {"q": "Which is evidence that Earth has warmed since the late 1800s?", "options": ["More earthquakes", "Rising global average temperature and rising sea level", "Shorter days", "More lunar eclipses"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Climate and Climate Change$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,1,1}'::int[], array[$j$Climate is measured over 30 years or more.$j$,$j$Sunlight is most direct near the equator.$j$,$j$They are greenhouse gases.$j$,$j$Measurements show rising temperature and sea level.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Climate and Climate Change$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Water Resources and Human Impact$j$, $j${"questions": [{"q": "About what percent of Earth's water is salt water?", "options": ["10 percent", "97 percent", "50 percent", "3 percent"]}, {"q": "All of the land that drains into a river, lake or bay is its:", "options": ["Delta", "Floodplain", "Watershed", "Aquifer"]}, {"q": "Fertilizer washing off many lawns and farms is an example of:", "options": ["Desalination", "Nonpoint source pollution", "Point source pollution", "Natural filtration"]}, {"q": "The Everglades is best described as a:", "options": ["Mountain range", "Desert", "Deep lake", "Wide, shallow, slow moving river of grass"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Water Resources and Human Impact$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,1,3}'::int[], array[$j$Only about 3 percent is fresh.$j$,$j$Water moves downhill across the watershed.$j$,$j$Runoff comes from many places.$j$,$j$It moves water slowly south.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Water Resources and Human Impact$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Earth's Resources, Stewardship and Careers$j$, $j${"questions": [{"q": "Which is a renewable resource when managed wisely?", "options": ["Coal", "Oil", "Natural gas", "Trees"]}, {"q": "Which is a nonrenewable resource?", "options": ["Tides", "Natural gas", "Sunlight", "Wind"]}, {"q": "The phrase reduce, reuse, recycle encourages people to:", "options": ["Use more plastic", "Burn trash in yards", "Waste less and recover materials", "Buy more things"]}, {"q": "A scientist who forecasts weather and warns about hurricanes is a:", "options": ["Paleontologist", "Oceanographer", "Geologist", "Meteorologist"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Earth's Resources, Stewardship and Careers$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,2,3}'::int[], array[$j$Forests can regrow if they are not cut faster than they recover.$j$,$j$It forms over millions of years.$j$,$j$Each step lowers waste.$j$,$j$Meteorologists study the atmosphere.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Earth's Resources, Stewardship and Careers$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: Oceans, Climate, Water and Stewardship$j$, $j${"questions": [{"q": "Ocean salinity averages about:", "options": ["35 parts per thousand", "3 parts per thousand", "350 parts per thousand", "0.35 parts per thousand"]}, {"q": "Warm surface currents are driven mainly by:", "options": ["Earthquakes", "Wind and the Coriolis effect", "Fish", "The Moon alone"]}, {"q": "Weather differs from climate because weather is:", "options": ["The average over 30 years", "The same everywhere", "Only about temperature", "Short term conditions at a place and time"]}, {"q": "The amount of carbon dioxide in the air has risen from about 280 parts per million to over:", "options": ["420 parts per million", "300 parts per million", "100 parts per million", "1000 parts per million"]}, {"q": "Less than 1 percent of Earth's water is easy to use because most is:", "options": ["Rain", "Lost in space", "Salt water or frozen or deep underground", "In clouds"]}, {"q": "Southeast Florida mainly draws drinking water from the:", "options": ["Great Lakes", "Appalachians", "Gulf Stream", "Biscayne aquifer"]}, {"q": "A bloom of algae caused partly by excess nutrients in water is a result of:", "options": ["Plate tectonics", "A solar eclipse", "Deposition", "Nonpoint source pollution"]}, {"q": "Which action best fits the idea of stewardship in Genesis 2:15?", "options": ["Dressing and keeping the earth with care", "Using resources without thinking", "Taking all and leaving nothing", "Ignoring pollution"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Oceans, Climate, Water and Stewardship$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,3,0,2,3,3,0}'::int[], array[$j$That is 3.5 percent.$j$,$j$Wind and Earth's rotation set up gyres.$j$,$j$Climate is the long term average.$j$,$j$Air samples and ice cores show the rise.$j$,$j$Very little is fresh and accessible.$j$,$j$It is a shallow aquifer vulnerable to salt water.$j$,$j$Extra nutrients feed algae growth.$j$,$j$Dominion means faithful care.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Oceans, Climate, Water and Stewardship$j$ on conflict (item_id) do nothing;
